import {
  Entity,
  PrimaryColumn,
  Column,
  ManyToOne,
  JoinColumn,
  Index,
  ForeignKey,
} from 'typeorm';
import { User } from './user.entity';

@Entity('students')
@Index('idx_students_semester', ['current_semester'])
export class Student {
  @PrimaryColumn('uuid')
  user_id: string;

  @Column({ type: 'varchar', length: 30, nullable: false, unique: true })
  student_number: string;

  @Column({ type: 'int', nullable: false })
  current_semester: number;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user: User;
}

import {
  Entity,
  PrimaryColumn,
  Column,
  ManyToOne,
  JoinColumn,
  Index,
  ForeignKey,
} from 'typeorm';
import { User } from './user.entity';

@Entity('students')
@Index('idx_students_semester', ['currentSemester'])
export class Student {
  @PrimaryColumn('uuid', { name: 'user_id' })
  userId: string;

  @Column({ type: 'varchar', length: 30, nullable: false, unique: true, name: 'student_number' })
  studentNumber: string;

  @Column({ type: 'int', nullable: false, name: 'current_semester' })
  currentSemester: number;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user: User;
}

import {
  Entity,
  PrimaryColumn,
  Column,
  ManyToOne,
  JoinColumn,
} from 'typeorm';
import { User } from './user.entity';

@Entity('system_admins')
export class SystemAdmin {
  @PrimaryColumn('uuid')
  user_id: string;

  @Column({ type: 'varchar', length: 30, nullable: true, unique: true })
  employee_number: string;

  @Column({ type: 'boolean', nullable: false, default: false })
  is_super_admin: boolean;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user: User;
}

import {
  Entity,
  PrimaryColumn,
  Column,
  ManyToOne,
  JoinColumn,
} from 'typeorm';
import { User } from './user.entity';

@Entity('system_admins')
export class SystemAdmin {
  @PrimaryColumn('uuid', { name: 'user_id' })
  userId: string;

  @Column({ type: 'varchar', length: 30, nullable: true, unique: true, name: 'employee_number' })
  employeeNumber: string | null;

  @Column({ type: 'boolean', nullable: false, default: false, name: 'is_super_admin' })
  isSuperAdmin: boolean;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user: User;
}
